arguments.command:
# LM Studio Health Check
echo "=== LM STUDIO CHECK ==="
if (Test-Path "http://100.67.202.80:3003/v1") {
    Write-Host "LM Studio is reachable"
} else {
    Write-Host "LM Studio not responding to path test"
}

# Simple ping check
echo "=== NETWORK CHECK ==="
ping -t 100.67.202.80 -n 1 -w 5000

# LM Studio API Check
echo "=== LM STUDIO API ENDPOINT ==="
$response = Invoke-RestMethod -Uri "http://100.67.202.80:3003/v1" -UseBasicParsing 2>&1
if ($LASTEXITCODE -eq 0) {
    Write-Host "LM Studio API is responding"
} else {
    Write-Host "LM Studio API returned error"
}

# Try status endpoint
echo "=== LM STUDIO STATUS ==="
Invoke-RestMethod -Uri "http://100.67.202.80:3003/api/status" -UseBasicParsing 2>&1 | Select-Object -First 5
